#include <vector>

double average_of_positives(const std::vector<int>& values) {
    int total;
    int count = 0;

    for (int i = 0; i < values.size(); ++i) {
        if (values[i] > 0) {
            total += values[i];
            ++count;
        }
    }

    if (count == 0) return 0.0;
    return static_cast<double>(total) / count;
}

